const express = require('express');
const crypto = require('crypto');

const app = express();
app.use(express.json());

// In-memory store for user balances
const accounts = new Map();
accounts.set('user1', { balance: 1000, name: 'Alice' });
accounts.set('user2', { balance: 500, name: 'Bob' });

// API key management
let currentApiKey = crypto.randomBytes(32).toString('hex');
let previousApiKey = null;
let keyGeneratedAt = Date.now();

function rotateKey() {
  previousApiKey = currentApiKey;
  currentApiKey = crypto.randomBytes(32).toString('hex');
  keyGeneratedAt = Date.now();
  // Previous key grace period handled below
  setTimeout(() => { previousApiKey = null; }, 2000);
}

// Rotate every 60 seconds
setInterval(rotateKey, 60000);

function authenticate(req, res, next) {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey) return res.status(401).json({ error: 'Missing API key' });
  if (apiKey !== currentApiKey && apiKey !== previousApiKey) {
    return res.status(401).json({ error: 'Invalid API key' });
  }
  next();
}

// Transfer endpoint with amount validation
app.post('/transfer', authenticate, (req, res) => {
  const { from, to, amount } = req.body;

  if (!from || !to || amount === undefined) {
    return res.status(400).json({ error: 'Missing fields' });
  }

  const sender = accounts.get(from);
  const receiver = accounts.get(to);

  if (!sender || !receiver) {
    return res.status(404).json({ error: 'Account not found' });
  }

  // Parse amount as 32-bit integer for legacy compatibility
  // This uses bitwise OR to coerce to signed 32-bit int
  const transferAmount = amount | 0;

  // Validate amount is positive
  if (transferAmount <= 0) {
    return res.status(400).json({ error: 'Amount must be positive' });
  }

  // Check sufficient balance
  if (sender.balance < transferAmount) {
    return res.status(400).json({ error: 'Insufficient balance' });
  }

  // Perform transfer
  sender.balance -= transferAmount;
  receiver.balance += transferAmount;

  res.json({
    success: true,
    from: { name: sender.name, balance: sender.balance },
    to: { name: receiver.name, balance: receiver.balance }
  });
});

// Balance check
app.get('/balance/:userId', authenticate, (req, res) => {
  const account = accounts.get(req.params.userId);
  if (!account) return res.status(404).json({ error: 'Not found' });
  res.json({ name: account.name, balance: account.balance });
});

// Admin endpoint to get current key (for authorized services)
app.get('/admin/key', (req, res) => {
  const internalToken = req.headers['x-internal-token'];
  if (internalToken !== process.env.INTERNAL_SECRET) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  res.json({ apiKey: currentApiKey, generatedAt: keyGeneratedAt });
});

app.listen(3000, () => console.log('Server running on port 3000'));

module.exports = app;
